UPDATE places SET name_english=place_name,state_name=(SELECT s.state_name FROM cities c JOIN states s ON s.id=c.state_id WHERE c.id=places.city_id),created_at='2026-10-02',updated_at='2026-10-02',verification_status='partial',verification_notes='Identity/source checked; live/provider metadata not fetched.',verified_at='2026-10-02' WHERE id BETWEEN 688000001 AND 688000105;
